import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class HeightAllTheSame {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());
        long total = (long) n * m;
        int mod = 998244353;
        if ((total & 1) != 0) {
            System.out.println(pow(r - l + 1, total, mod));
        } else {
            int k = r - l + 1;
            int e = r / 2 - l / 2;
            if ((l & 1) == 0) {
                e++;
            }
            int o = k - e;
            long ans = pow(e + o, total, mod);
            ans = (ans + pow(e - o, total, mod)) % mod;
            ans = (ans * pow(2, mod - 2, mod)) % mod;
            System.out.println(ans);
        }
    }

    static long pow(long a, long power, int mod) {
        if (power == 0) {
            return 1;
        }
        if (power == 1) {
            return a;
        }
        long exp = power < 0 ? -power : power;
        if (exp == 1) {
            return a % mod;
        }
        long result = 1;
        long base = a % mod;
        for (long bit = Long.highestOneBit(exp); bit != 0; bit >>= 1) {
            result = (result * result) % mod;
            if ((exp & bit) != 0) {
                result = (result * base) % mod;
            }
        }
        return result;
    }
}
